// Offline evaluation only. Recipes are generated by the existing Core, never patched.
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { buildCanonicalCast } from '../../src/core/normalize.js';
import { lineFromSum } from '../../src/core/physics.js';
import { JIAZI60 } from '../../src/core/constants.js';
import { buildYearMonthHourPillars, buildDateDisplayText, getTodayJiaziIndex } from '../../src/core/ganzhi.js';
import { evaluateRules } from '../../src/rules/engine.js';
import { readCorpus } from '../../src/knowledge/load.js';
import { buildKnowledgePair } from '../../src/ai/knowledge-input.js';
import { validateAiValue } from '../../src/ai/schemas.js';
const root = fileURLToPath(new URL('../../', import.meta.url));
const read = p => JSON.parse(fs.readFileSync(root+p,'utf8'));
export const digest = x => createHash('sha256').update(JSON.stringify(x)).digest('hex');
const need = (ok,message) => { if(!ok) throw Error(message); };
export function regenerate(recipe,question,case_id) {
  const old=process.env.TZ; process.env.TZ=recipe.timezone;
  try {
    const now=new Date(recipe.timestamp),day=JIAZI60[recipe.explicit_day_index];
    need(getTodayJiaziIndex(now)===recipe.explicit_day_index,'Recipe calendar mismatch');
    return buildCanonicalCast({lines:recipe.sums.map(lineFromSum),source:'manual',question,
      createdAt:now.getTime(),castId:`phase7-unseen-${case_id}`,
      calendar:{now,day,ymh:buildYearMonthHourPillars(day.stem,now),dateText:buildDateDisplayText(now)}});
  } finally { if(old===undefined) delete process.env.TZ;else process.env.TZ=old; }
}
// Deliberately excludes question, cast identifiers and display summaries.
export const castFingerprint = c => digest({calendar:c.calendar,hexagram:c.hexagram,lines:c.lines});
export const shapeFingerprint = c => digest({hexagram:c.hexagram.primary.name,lines:c.lines.map(l=>[l.yin_yang,l.moving])});
export function assertFresh(cases) {
  const previous=read('experiments/phase6/cases.json').cases;
  const oldCasts=[...previous.map(c=>c.canonical),...[1,2,3].map(n=>read(`experiments/phase7/fixtures/compat-${n}.json`))];
  const previousSums=new Set(previous.filter(c=>c.source.kind==='core_recipe').map(c=>JSON.stringify(c.source.sums)));
  const seen=new Set(),shapes=new Set();
  for(const c of cases){
    need(!previousSums.has(JSON.stringify(c.recipe.sums)),'Reused Phase 6 recipe');
    need(!oldCasts.some(x=>shapeFingerprint(x)===shapeFingerprint(c.canonical)),'Reused historical fixture shape');
    const fingerprint=castFingerprint(c.canonical),shape=shapeFingerprint(c.canonical);
    need(!seen.has(fingerprint)&&!shapes.has(shape),'Duplicate new cast');seen.add(fingerprint);shapes.add(shape);
  }
}
export function conditionHits(canonical,rule_result,condition) {
  const ids={ying_generates:['YING-GENERATE-SHI-001'],shi_generates:['SHI-GENERATE-YING-001'],month_clash:['MONTH-CLASH-001'],month_combine:['MONTH-COMBINE-001'],static_day_clash:['DAY-CLASH-001'],advance:['MOVE-ADVANCE-001'],retreat:['MOVE-RETREAT-001'],void:['LINE-VOID-001'],jiazi_void:['LINE-VOID-001'],return:['MOVE-RETURN-GENERATE-001','MOVE-RETURN-CONTROL-001'],hidden:['HIDDEN-FLY-GENERATE-001','HIDDEN-FLY-CONTROL-001']};
  return rule_result.hits.filter(h=>ids[condition]?.includes(h.rule_id))
    .filter(h=>condition!=='static_day_clash'||!canonical.lines[h.target.line-1].moving)
    .filter(()=>condition!=='jiazi_void'||canonical.calendar.kongwang.join('')==='戌亥');
}
export function referencePack() {
  const corpus=readCorpus();
  return corpus.units.filter(u=>u.verification_status==='reviewed').sort((a,b)=>a.knowledge_id.localeCompare(b.knowledge_id)).map((u,i)=>{
    const segment=corpus.segments.find(s=>s.segment_id===u.segment_ref.segment_id);
    const source=corpus.sources.find(s=>s.source_id===segment.source_ref.source_id);
    return {source_reference_id:`reference-${i+1}`,title:source.title,edition:source.edition,locator:segment.locator,
      source_url:source.provenance.source_url,original_text:u.original_text,normalized_statement:u.normalized_statement,
      applicable_conditions:u.applicable_conditions,exclusions:u.exclusions,exceptions:u.exceptions};
  });
}
export function neutralMaterials(c,pair) {
  const facts=[];
  const walk=(value,pointer)=>{
    if(value&&typeof value==='object')for(const [key,v]of Object.entries(value))walk(v,`${pointer}/${key}`);
    else facts.push({fact_id:`field-${facts.length+1}`,category:c.category,statement:`${pointer} = ${JSON.stringify(value)}`,evidence:[{path:pointer,value}]});
  };
  for(const field of ['calendar','hexagram','lines'])walk(pair.off.input.C_canonical_cast[field],`/${field}`);
  for(const [i,h]of c.rule_result.hits.entries()) facts.push({fact_id:`relation-${i+1}`,category:c.category,
    statement:{target:h.target,label:h.result.label,from:h.result.from??null,to:h.result.to??null},evidence:h.evidence});
  return {case_id:c.case_id,question:c.question,follow_up:c.follow_up,facts,checklist:c.checklist};
}
export function loadCases() {
  const data=read('experiments/phase7/evaluation/cases.json'),manifest=read('experiments/phase7/evaluation/manifest.json');
  validateAiValue(data,read('experiments/phase7/evaluation/cases.schema.json'));
  need(digest(data)===manifest.cases_hash,'Frozen case manifest mismatch');
  need(data.cases.length===12&&new Set(data.cases.map(c=>c.case_id)).size===12,'Need 12 unique cases');
  assertFresh(data.cases);
  const corpus=readCorpus();
  for(const c of data.cases){
    assert.deepEqual(regenerate(c.recipe,c.question,c.case_id),c.canonical);
    assert.deepEqual(evaluateRules(c.canonical),c.rule_result);
    need(conditionHits(c.canonical,c.rule_result,c.condition).length,'Case condition not satisfied');
    const pair=buildKnowledgePair({canonical:c.canonical,corpus,case_id:c.case_id,query:c.query});
    assert.deepEqual(pair.archive,c.expected.archive);
    assert.deepEqual(pair.archive.selected_knowledge_ids,c.expected.selected_ids);
    need(c.expected.zero_match===(pair.on.input.F_literature_context.items.length===0),'Unexpected zero match');
    if(c.expected.zero_match)need(pair.off.text===pair.on.text,'Zero pair differs');
    need(digest(c.checklist)===c.checklist_hash,'Checklist changed');
  }
  return {data,manifest};
}
